typedef struct{SatchelSwitchProcess*p;uint64_t protected_address;uint32_t string_size;} Context;
static SatchelSwitchIdentityReservation native(const SatchelGuestVIReservation*r){return(SatchelSwitchIdentityReservation){r->version,r->size,r->process_id,r->generation,r->address,r->length};}
static int claim(void*ctx,SatchelCPUProbe*cpu,const SatchelGuestVIReservation*r){SatchelSwitchIdentityReservation d=native(r);return satchel_switch_process_claim_identity(((Context*)ctx)->p,cpu,&d);}
static int validate(void*ctx,SatchelCPUProbe*cpu,const SatchelGuestVIReservation*r){SatchelSwitchIdentityReservation d=native(r);return satchel_switch_process_validate_identity(((Context*)ctx)->p,cpu,&d);}
static int guard(void*ctx,SatchelCPUProbe*cpu,uint64_t a,size_t n){int overlap=1;return satchel_cpu_probe_physical_overlap(cpu,a,n,((Context*)ctx)->protected_address,4096,&overlap)&&!overlap;}
static int read_guest(void*ctx,uint64_t a,void*out,size_t n){return satchel_cpu_probe_read(satchel_switch_process_cpu(((Context*)ctx)->p),a,out,n);}
