 CHECK(satchel_cpu_probe_set_permissions(cpu,d.address,4096,0,3)==SATCHEL_CPU_MAP_OK);CHECK(!satchel_switch_process_validate_identity(p,cpu,&d));uint64_t old=read64(cpu,output+48);CHECK(invoke(&c,owner,&b,&e,3,output+48,layer)==SATCHEL_GVI_RESERVATION);CHECK(read64(cpu,output+48)==old);CHECK(satchel_cpu_probe_set_permissions(cpu,d.address,4096,3,0)==SATCHEL_CPU_MAP_OK);CHECK(satchel_switch_process_validate_identity(p,cpu,&d));
 uint64_t alias=d.address+0x40000000;CHECK(satchel_cpu_probe_set_permissions(cpu,d.address,4096,0,3)==SATCHEL_CPU_MAP_OK);CHECK(satchel_cpu_probe_map_alias(cpu,alias,d.address,4096)==SATCHEL_CPU_MAP_OK);CHECK(!satchel_switch_process_validate_identity(p,cpu,&d));CHECK(invoke(&c,owner,&b,&e,3,output+48,layer)==SATCHEL_GVI_RESERVATION);CHECK(satchel_cpu_probe_unmap_alias(cpu,alias,d.address,4096)==SATCHEL_CPU_MAP_OK);CHECK(satchel_cpu_probe_set_permissions(cpu,d.address,4096,3,0)==SATCHEL_CPU_MAP_OK);CHECK(invoke(&c,owner,&b,&e,3,output+48,layer)==SATCHEL_GVI_OK);CHECK(read64(cpu,output+48)==window);
 CHECK(satchel_guest_vi_release_native(owner,ref)==SATCHEL_GVI_OK);CHECK(invoke(&c,owner,&b,&e,4,layer,0)==SATCHEL_GVI_OK);CHECK(invoke(&c,owner,&b,&e,5,display,0)==SATCHEL_GVI_OK);CHECK(satchel_guest_vi_try_destroy(&owner)==SATCHEL_GVI_OK);CHECK(satchel_guest_vi_create(&config,cpu,claim,&c,&owner)==SATCHEL_GVI_RESERVATION&&!owner);CHECK(satchel_switch_process_validate_identity(p,cpu,&d));satchel_switch_process_destroy(p);
